window.SAQ_PAPER_QUESTIONS["2023-1-pah"]=[{"number":1,"title":"","stemText":"A 68 year old homeless man has been brought in by ambulance with shortness of breath. He has had a week of fevers and cough. His chest x-ray is shown below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 radiographic abnormalities. (3 marks)"},{"id":"b","label":"Part B","prompt":"List the 2 most likely differential diagnoses. (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 investigations you would perform in order to help clarify the diagnosis, including\njustification. (3 marks)\nHis vital signs are:\n\nTemp\n38.8 degrees Pulse 120 /min\n\nBP\n84/50 mmHg O2 sats 86% 6L O2 via Hudson mask"},{"id":"d","label":"Part D","prompt":"State your 3 most important treatment measures. (3 marks)"}],"propPages":["asset:img5c1ad8a18b729a8046"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Consolidation left upper zone</div><div class=\"answer-line\">Cavitating lesion/multiple cavitating lesions with</div><div class=\"answer-line\">air fluid level left upper zone</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Abscess</div><div class=\"answer-line\">Malignancy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">CT scan – looking for other signs malignancy</div><div class=\"answer-line\">BC – aim to identify organism/confirm abscess and to target Abs in the coming days</div><div class=\"answer-line\">Sputum culture – same as above</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">IV N/S 1L stat aiming for BP systolic 100mmHg /MAP 65</div><div class=\"answer-line\"><strong>IV abs</strong> – ceftriaxone 1g bd, plus metronidazole 500mg bd (prob should add gent and vanc)</div><div class=\"answer-line\">O2 – increase FiO2 aim sats &gt;92%, either HFNP or NRB 15L</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 72-year-old female is undergoing a Bier’s Block for reduction of a right distal radius fracture. She has no previous medical history. 20 minutes into the procedure, the patient has a generalised seizure.\nHer vital signs are:\nPulse 110 /min\n\nBP\n85/45 mmHg O2 sats 85% room air","parts":[{"id":"a","label":"Part A","prompt":"State 4 components of your initial management. Include end-points where appropriate.\n(4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 investigations you would perform, with justification. (3 marks)"},{"id":"c","label":"Part C","prompt":"State 5 safety steps in the Bier’s Block procedure that would reduce the risk of seizures. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Apply O2 via mask</strong> – aim sats &gt;92%</div><div class=\"answer-line\">Terminate seizure – IV midaz 5mg</div><div class=\"answer-line\">IV N/S – 1L stat aiming BP &gt;100 Systolic</div><div class=\"answer-line\"><strong>IV HCO3</strong> – initial 50-100mmol aiming for serum alkalinisation – pH 7.5</div><div class=\"answer-line\">(accept intralipid given books)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">ECG – looking for broad QRS as evidence of Na channel cardiac toxicity, establish rhythm</div><div class=\"answer-line\">VBG – look for pH, aim of therapy will serum alkalinisation 7.5</div><div class=\"answer-line\">BSL – exclude hypoglycaemia as cause of seizure</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Check both cuffs working correctly</div><div class=\"answer-line\">Cuff inflated 100mmHg above SBP and check absent brachial pulse</div><div class=\"answer-line\">Cuff inflated for minimum of 25 minutes</div><div class=\"answer-line\">Prilocaine dosing safe range 0.5% 3mL/kg</div><div class=\"answer-line\">Continuous cardiac monitoring for early detection LA toxicity</div><div class=\"answer-line\">Visual observations for early detection LA toxicity</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"You are the consultant on a Monday evening shift in a busy tertiary emergency department. Your department is suffering from significant access block with 19 patients awaiting admission to an inpatient bed.","parts":[{"id":"a","label":"Part A","prompt":"List 6 complications of patient care that might ensue from this situation. (6 marks)\nIn response to prolonged ED length of stay times, you have been tasked to work on solutions to this problem."},{"id":"b","label":"Part B","prompt":"State 5 potential solutions to improve ED length of stay times. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Delays in patient assessment and treatment</div><div class=\"answer-line\">Increased risk of patient exposure to error</div><div class=\"answer-line\">Increased length of stay in hospital</div><div class=\"answer-line\">Increased inpatient mortality</div><div class=\"answer-line\">Increased ‘did not wait’ for treatment</div><div class=\"answer-line\">Ambulance ramping leading to longer community wait times</div><div class=\"answer-line\">Others will be acceptable</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Main factor will be accessing inpatient beds</div><div class=\"answer-line\">Hospital avoidance schemes eg HITH</div><div class=\"answer-line\">Factors that facilitate inpatient discharge – eg more frequent ward rounds</div><div class=\"answer-line\">Direct admission process</div><div class=\"answer-line\">Shortening patient work-up times – eg access to radiology improvement / pathology</div><div class=\"answer-line\">Focus on early senior decision making in the ED</div><div class=\"answer-line\">Others OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 9 week old baby boy has presented with vomiting and lethargy.\nA venous blood gas is provided below. Reference range\n\npH\n7.28 7.35-7.45\n\npCO2\nmmHg 35-45\n\nHCO3\nmmol/L 20-28\n\nNa\n122 mmol/L 135-145\n\nK\n5.9 mmol/L 3.5-4.5\n\nCl\nmmol/L 88-108\n\nGlucose\n2.8 mmol/L 3.0-5.5\n\nLactate\n1.5 mmol/L <2.0","parts":[{"id":"a","label":"Part A","prompt":"State the most likely diagnosis, supported by the abnormalities identified. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 abnormalities on examination that would support your diagnosis. (3 marks)\nThe baby has the following vital signs: Central CRT 5s\n\nHR\n190 /min\n\nBP\n70/40 mmHg\n\nRR\n/min\n\nT\n37.4 degrees\n\nSats\n99% room air"},{"id":"c","label":"Part C","prompt":"State 3 components of your management of this baby, with justification and end-points where appropriate. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>NAGMA</strong> (AG = 9)</div><div class=\"answer-line\">Hyponatraemia with Hyperkalaemia (mineralocorticoid deficiency)</div><div class=\"answer-line\"><strong>Hypoglycaemia </strong></div><div class=\"answer-line\">Congenital adrenal hyperplasia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pigmented scrotum</div><div class=\"answer-line\">Pubic hair</div><div class=\"answer-line\">Ambiguous genitalia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV fluids – 20mL/kg n/saline bolus (or similar) aiming CRT &lt;3s</div><div class=\"answer-line\"><strong>IV dextrose</strong> 2-5mL/kg aiming BSL &gt;4</div><div class=\"answer-line\"><strong>IV hydrocortisone</strong> 25mg IV (stress dose)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 56 year old woman has been brought to the ED after being found on her bathroom floor.\nInitial assessment reveals the following vital signs:\n\nGCS\nE1 V2 M4 Pulse 100 /min\n\nBP\n120/75 mmHg\n\nRR\n/min O2 sats 99% 6L O2 via Hudson mask Temperature 36.5 degrees Venous blood gas has demonstrated a mild lactic acidosis with a serum sodium of 105 mmol/L. Your conclusion is that the patient has suffered a seizure due to hyponatraemia.","parts":[{"id":"a","label":"Part A","prompt":"State your management specific to this patient’s hyponatraemia. Include end-points. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 5 key aspects of your collateral history that will aid in your assessment of the cause of her hyponatraemia. Include the relevance of each. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 5 key aspects of your examination that will aid in your assessment of the cause of her hyponatraemia. Include the relevance of each. (5 marks)"},{"id":"d","label":"Part D","prompt":"List 5 investigations that will aid in your assessment of the cause of her hyponatraemia. Include the relevance of each. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">aiming for acute increase approx. 5mmol/L</div><div class=\"answer-line\">Then target 0.5-1 mmol/L/hr for 24hrs</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Water consumption / psych Hx – large amount would suggest psychogenic polydipsia</div><div class=\"answer-line\">Medication Hx – many cause SIADH eg carbamazepine, thiazides, SSRIs etc</div><div class=\"answer-line\">Hx thyroid disease – cause hyponatremia</div><div class=\"answer-line\">Hx of organ failure (cardiac, liver, renal)</div><div class=\"answer-line\">Hx of known malignancy or recent symptoms of concern for occult malignancy (weight loss, night</div><div class=\"answer-line\">sweats, confusion etc)</div><div class=\"answer-line\">Hx of recreational drug use ie MDMA</div><div class=\"answer-line\">Others ok</div><div class=\"answer-line\">Hx adrenal disease ie addisons</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Fluid status – periph oedema/crackles etc vs dehydration</div><div class=\"answer-line\">GIT exam ie jaundice, signs CLD</div><div class=\"answer-line\">Neck exam - ?goitre/mass</div><div class=\"answer-line\">Generalised pigmentation (particularly nail folds, skin creases) ie adrenal insufficiency</div><div class=\"answer-line\">Signs supportive of lung/cerebral malignancy – cachexia, supraclavicular nodes etc</div><div class=\"answer-line\">Others likely ok</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Renal function – exclude renal failure</div><div class=\"answer-line\">TFTs – exclude hypothyroidism as cause</div><div class=\"answer-line\">Urinary osmolarity <strong>/ urinary sodium</strong> – indicative of ADH activity</div><div class=\"answer-line\">Random cortisol – adrenal status</div><div class=\"answer-line\">Drug  levels ie carbamazapine/ valproate – if suspected med related or present on drug history</div><div class=\"answer-line\">CXR – identify lung path ie cancer or pulm oedema</div><div class=\"answer-line\">CT Head - ?malignancy/SOL</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 4 year old female has presented with a 2 night history of a worsening loud barking cough.","parts":[{"id":"a","label":"Part A","prompt":"List 4 examination features consistent with severe croup. (4 marks)\nThe patient has severe croup."},{"id":"b","label":"Part B","prompt":"State 3 components of your initial management. (3 marks)\nDespite your initial management, the patient requires intubation."},{"id":"c","label":"Part C","prompt":"State 5 anticipated difficulties you may encounter in the peri-intubation period and how you will prepare for each. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Stridor at rest</div><div class=\"answer-line\">Biphasic stridor</div><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Agitation, drowsiness</div><div class=\"answer-line\">Marked increase or decrease RR</div><div class=\"answer-line\">Marked chest wall retraction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Oxygen supplementation however you like</div><div class=\"answer-line\">Keep the child calm (use parents)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Agitation – pre-oxygenate sitting / use of ketamine as dissociative to allow pre-oxygenation</td><td>Upper airway oedema – smaller size tube ie 1 size down) ie size 4</td></tr><tr><td>Increased secretions – double suction</td><td>Airway obstruction on lying flat – intubate at 30degrees</td></tr><tr><td>Atelectasis/collapse post induction – PEEP post intubation</td><td>Difficult preoxygenation – maintain highflow/PEEP throughout</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 54 year old female was brought in by ambulance following a high-speed motorbike accident with lower back and pelvic pain. Her pelvic x-ray is shown below.","parts":[{"id":"a","label":"Part A","prompt":"State the abnormalities shown on the x-ray. (4 marks)"},{"id":"b","label":"Part B","prompt":"State 4 non-orthopaedic injuries directly associated with this pelvic injury that may be\npresent. For each injury, provide key examination findings that would indicate its presence. (8 marks) Injury Key examination findings"}],"propPages":["asset:imgd52605e6adfbde0b06"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Fracture through sacrum – note SIJ intact with vertical displacement of lateral fragment</div><div class=\"answer-line\">Acetabular fracture</div><div class=\"answer-line\">Inferior ramus fracture</div><div class=\"answer-line\">Symphyseal disruption</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Bladder - haematuria</td><td>Bowel – PR blood/bone on DRE</td></tr><tr><td>Urethral – blood at meatus/retention/boggy vulval swelling</td><td>Vaginal – PV blood, bone on spec exam/PV</td></tr><tr><td>Vascular – hypotension, pulse deficit</td><td>Nerve  - foot drop etc</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 28-year-old female presents at 30 weeks gestation with continuous lower abdominal pain and PV bleeding.","parts":[{"id":"a","label":"Part A","prompt":"List 5 features on history that would increase the risk of antepartum haemorrhage. (5 marks)"},{"id":"b","label":"Part B","prompt":"State 4 key investigations, with justification for each. (4 marks)\nThe patient starts to bleed heavily. Vital signs are as follows:\n\nHR\n130 /min\n\nBP\n70/50 mmHg\n\nRR\n/min\n\nSats\n94% room air"},{"id":"c","label":"Part C","prompt":"State 3 key components of your management, with end points and rationale. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Known placenta praevia</div><div class=\"answer-line\">Abdominal trauma</div><div class=\"answer-line\">Smoking</div><div class=\"answer-line\">Amphetamine abuse</div><div class=\"answer-line\">Previous caesarean section/uterine surgery</div><div class=\"answer-line\">Advanced maternal age</div><div class=\"answer-line\">Assisted reproduction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>USS – to confirm diagnosis, assess for placenta praevia or abruption</td><td><strong>CTG</strong> – assess foetal well being/exclude foetal distress</td></tr><tr><td><strong>G&amp;H</strong> – blood transfusion may be required in setting of APH</td><td>Coagulation studies – exclude DIC</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>PRBC</strong> – aim SBP &gt;80</div><div class=\"answer-line\">Steroids – betamethasone 11.4mg IM</div><div class=\"answer-line\">Obstetric referral for urgent delivery</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 45 year old man presents with severe upper leg pain following a fishing trip.\nA clinical photo of his leg is shown below.","parts":[{"id":"a","label":"Part A","prompt":"State the likely diagnosis and list 3 relevant features demonstrated in the clinical photo. (4 marks) Likely diagnosis Relevant features"},{"id":"b","label":"Part B","prompt":"List 4 possible pathogens that could be responsible for the above condition. (4 marks)"},{"id":"c","label":"Part C","prompt":"List 4 relevant investigations you may perform, with a rationale for each. (4 marks)\nThe patient has the following vital signs: Pulse 130 /min\n\nBP\n90/50 mmHg\n\nRR\n/min O2 sats 99% room air Temperature 40.1 degrees"},{"id":"d","label":"Part D","prompt":"Give your antibiotic regime. (2 marks)"},{"id":"e","label":"Part E","prompt":"State 3 other aspects of your management. (3 marks)\nPAH 2023.1 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":["asset:imgf497bfc5c721a24f6b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Erythema</div><div class=\"answer-line\">Central necrosis</div><div class=\"answer-line\">Blistering</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Streptococci</div><div class=\"answer-line\">Clostridium</div><div class=\"answer-line\">Vibrio sp</div><div class=\"answer-line\">Aeromonas sp</div><div class=\"answer-line\">E.coli</div><div class=\"answer-line\">Bacteroides</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>VBG – metabolic status</td><td>Blood cultures – confirm and rationalise Abx</td></tr><tr><td>Wound swab – identify organism, higher yield than BCs</td><td>Imaging – xray/USS to confirm gas – extent of infection to guide surgical planning</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Meropenem 1g IV Q8H</div><div class=\"answer-line\">Vancomycin 30mg/kg IV loading dose</div><div class=\"answer-line\">Ciprofloxacin 400mg IV Q8H</div><div class=\"answer-line\">Clindamycin 600mg IV Q8H (or lincomycin 600mg)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">IV fluids</div><div class=\"answer-line\"><strong>Referral for surgical debridement </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 2 month old boy has been brought to the ED with pallor, sweating and poor feeding.\nAn ECG has been performed and is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the likely diagnosis, supported by 3 ECG findings. (4 marks) Likely diagnosis ECG findings"},{"id":"b","label":"Part B","prompt":"List 3 treatment options for management of this problem. For each, provide the clinical\ncircumstance in which the treatment is indicated. (6 marks) Treatment option Clinical circumstance"}],"propPages":["asset:img0eb3ed1f778e16ebcd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Regular</div><div class=\"answer-line\">Narrow Complex QRS</div><div class=\"answer-line\">Normal infant axis (RAD)</div><div class=\"answer-line\">Rate appox 300/min</div><div class=\"answer-line\">Accept retrograde P wave seen in QT segment</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Vagal Manoeuvres (ice-cold flannel/ diving reflex etc) – indicated in well looking child, normal</td><td>perfusion</td></tr><tr><td>IV chemical cardioversion – adenosine – indicated in well child with failure of vagal response to non-</td><td>invasive measures (NOTE ONLY 1 mark for medications ie not both adenosine AND verapamil)</td></tr><tr><td>DC Cardioversion – child with evidence decompensation (ie congestive cardiac failure, poor</td><td>perfusion, hypotension)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"You are assessing the results of a recent study for presentation at your department’s journal club.","parts":[{"id":"a","label":"Part A","prompt":"List 6 types of bias that can affect the validity of a study’s results. Give a brief explanation of each. (12 marks) Type of bias Explanation"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">2. Observer bias: tendency of researchers to wish see an effect, whether present or not</div><div class=\"answer-line\">3. Performace bias: unequal care between study groups ie controls being undertreated</div><div class=\"answer-line\">4. Regression to the mean: where a characteristic regresses to population mean over time with</div><div class=\"answer-line\">potentially misleading attribution to the treatment (ie correlation)</div><div class=\"answer-line\">Other biases such as:</div><div class=\"answer-line\">5. Interviewer bias:  distortion of responses due to the way participants are asked</div><div class=\"answer-line\">6. Publication bias:  tendency for positive studies to get published can lead to p-hacking or data</div><div class=\"answer-line\">dredging to find ‘positive results’ with less clinical relevance or real-world meaning</div><div class=\"answer-line\">7. Researcher bias – tendency to see positive findings whether truly present or not (can be</div><div class=\"answer-line\">deliberate or subconscious)</div><div class=\"answer-line\">8. Response bias: where respondents (typically in surveys etc) provide inaccurate information</div><div class=\"answer-line\">(includes biases such as acquiesence/ demand characteristics/ social desirability/ courtesy /</div><div class=\"answer-line\">question order/ extreme responding)</div><div class=\"answer-line\">9. Selection bias (many types)</div><div class=\"answer-line\">Others likely also acceptable</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 25 year old man has been brought to the ED after a motorbike accident.\nHe was intubated in the field due to severe respiratory distress. His chest x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 important injuries demonstrated on the chest x-ray. Provide the supportive radiographic abnormalities for each. (8 marks) Injury Supportive radiographic abnormalities Following comprehensive assessment, no other injuries were identified. His vitals signs are: Pulse 130 /min\n\nBP\n70/40 mmHg O2 sats 92%\n\nFiO2 1.0"},{"id":"b","label":"Part B","prompt":"State 4 key components of his management. (4 marks)\nFollowing your management, the patient’s vital signs have normalised."},{"id":"c","label":"Part C","prompt":"List 3 potential complications that might arise in the next hour. For each, state your\nmanagement. (6 marks) Complication Management"}],"propPages":["asset:img0fffca8fdd62ccf698"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Rt pneumothorax  (tension reasonable)– mediastinal shift to Lt, deep sulcus sign on Rt,</td><td>subcutaneous emphysema/ visible lung edge with no markings outside</td></tr><tr><td>Massive Rt haemothorax – hyperdensity filling lateral pleural recess</td><td>Radiologic flail chest on Rt mid ribs with visible displaced fractures to lateral ribs</td></tr><tr><td>Rt pulmonary contusion – fluffy airspace opacification heterogenously distributed through Rt lung</td><td>(most dense at area of flail chest)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Blood only volume resuscitation with target BP &gt;80 (mentation not accepted as intubated)</div><div class=\"answer-line\">Cardiothoracic surgical attendance for consideration OT thoracotomy given HTX + shock</div><div class=\"answer-line\">TXA 1gm bolus + infusion</div><div class=\"answer-line\">Supportive cares with normothermia etc</div><div class=\"answer-line\">Increase PEEP if remains hypoxic post ICC insertions</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Recurrence of tension from air/blood - management: restoration of patency of drains or insertion of</td><td>further drains/use of suction etc</td></tr><tr><td>Re-expansion/negative pressure pulmonary oedema to left lung – management with increasing PEEP</td><td>Traumatic DIC – management with targeted product replacement and frequent sampling to assess</td></tr><tr><td>coagulation ie ROTEM or COAGs</td><td>Haemorrhagic shock from ongoing bleeding - transfusion</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 40 year old man has presented to the ED with a rash on his torso of 5 days duration.\nThe rash began soon after returning from a holiday to Vietnam.","parts":[{"id":"a","label":"Part A","prompt":"State 6 features of your history, including the relevance of each. (6 marks)"},{"id":"b","label":"Part B","prompt":"State 6 features of your examination, including the relevance of each. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Specific timing of travel and return/delay to rash onset – ie if &gt;7 days between return and onset,</div><div class=\"answer-line\">excludes dengue</div><div class=\"answer-line\">Areas visited – may change potential exposures ie dengue/ other infectious agents</div><div class=\"answer-line\">Activities ie tattoos/ IVDU or sexual encounters – increases risk of specific BBVs/ STIs/ Endocarditis</div><div class=\"answer-line\">Contact exposures ie unwell contacts and timing may explain transmissable illness</div><div class=\"answer-line\">Vaccination status – alters Pre-test probability of different infectious causes</div><div class=\"answer-line\">Associated symptoms/prodrome ie GIT symptoms raises possiblity viral hepatitis or typhoid</div><div class=\"answer-line\">PMHx – ie autoimmune illness ie SLE, prior dermatological issues</div><div class=\"answer-line\">Recreational drug/prescription or OTC drug use – temporal association may indicate causality of</div><div class=\"answer-line\">hypersensitivity</div><div class=\"answer-line\">Prior allergies and types of responses ?typical for patient</div><div class=\"answer-line\">History of fevers/ febrile episodes – nature of (ie cycles/rigors etc) may indicate specific patterns</div><div class=\"answer-line\">Many others likely ok if well justified</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Vital signs – fever consistent with infectious causes/ hypotension concerning for systemic illness</div><div class=\"answer-line\">Peripheral signs of endocarditis ie splinters/ Oslers nodes/ Janeway lesions</div><div class=\"answer-line\">Examination for tattoos/ stigmata IVDU</div><div class=\"answer-line\">Focal signs infection ie crackles – indicates likely focus of infection</div><div class=\"answer-line\">Meningism – may support CNS infection</div><div class=\"answer-line\">Lymph node exam – may indicate focus of infection or systemic illness of generalised</div><div class=\"answer-line\">Hepatomegaly/tenderness - focal differentials (ie hepatic abscess/hepatitis)</div><div class=\"answer-line\">Splenomegaly – concerning for malaria/ other causes of thrombocytopaenia</div><div class=\"answer-line\">Jaundice – may suggest hepatic faliure or haemolysis</div><div class=\"answer-line\">Murmur (endocarditis)</div><div class=\"answer-line\">Rash specifics – distribution (can be characteristic) - blanching vs haemorrhagic, vasculitic</div><div class=\"answer-line\">Joints for arthritis (suggestive systemic/ autoimmune causes)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"An 88 year old woman has been brought to the ED from her nursing home with fever, flank pain and vomiting. You have assessed her to have pyelonephritis.","parts":[{"id":"a","label":"Part A","prompt":"List 3 common urinary pathogens. (3 marks)\nYou have decided that she needs admission for intravenous antibiotic therapy."},{"id":"b","label":"Part B","prompt":"State 4 different antibiotic regimes you might use. For each, provide the clinical conditions that would make it the most appropriate choice. (4 marks) Antibiotic regime Clinical indication The patient has significant hypotension despite intravenous fluid therapy. You are considering whether to begin a noradrenaline infusion."},{"id":"c","label":"Part C","prompt":"State 5 factors you would consider in determining whether admission to the intensive care unit for vasopressor support is appropriate for this patient. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Escherichia Coli</div><div class=\"answer-line\">Klebsiella pneumoniae</div><div class=\"answer-line\">Proteus Mirabilis</div><div class=\"answer-line\">Enterococcal species</div><div class=\"answer-line\">Group B Strep</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Aminoglycoside (Tobramycin or Gentamicin) 5mg/kg + Ampicillin 1gm – where no special</td><td>circumstances exist</td></tr><tr><td>IF PENICILLIN hypersensitive:</td><td>Aminoglycoside as above MONOTHERAPY</td></tr><tr><td>If prior gentamicin complications (ie neuromuscular disease or ototoxicity) or renal impairment</td><td>precluding ongoing therapy with aminoglycoside:</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Likelihood of clinical recovery ie severity of illness in context of physiologic reserve/frailty)</div><div class=\"answer-line\">Pre-existing ceiling of care (ie AHD)</div><div class=\"answer-line\">Patient expressed wishes where capacity present</div><div class=\"answer-line\">Presence of life-limiting comorbidities (active malignancy, dementia, severe COPD)</div><div class=\"answer-line\">QOL (ie mobility and cognitive status/care-dependence)</div><div class=\"answer-line\">Others likely ok if justified</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 40 year old woman has been brought to the ED after falling off a motorbike and sustaining an isolated right leg injury. A clinical photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the injury shown. (3 marks) The patient has normal vital signs."},{"id":"b","label":"Part B","prompt":"State 3 distinct components of your examination of the leg. Provide clinical relevance for each. (3 marks)"},{"id":"c","label":"Part C","prompt":"State 6 components of your management of this patient. (6 marks)"}],"propPages":["asset:img0b3df5d119ba5565f6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Open/Compound fracture Rt mid lower leg (shin acceptable)</div><div class=\"answer-line\">Large soft tissue defect (approx 10-15cm)</div><div class=\"answer-line\">Exposed bone fragment through wound</div><div class=\"answer-line\">Accept Gustillo grade IIIB</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Peripheral vascular exam</strong> – pulses and cap refill time – need for CT Angiogram to identify nature of</td><td>injury/site and inform management strategy</td></tr><tr><td>Neurologic exam for areas of sensory loss suggesting nerve injury at level of wound (full motor exam</td><td>not reasonable)</td></tr><tr><td>Wound exam – degree of contamination (ie gross contamination) - may need wash in ED</td><td>Skin near wound for any areas under pressure or with evidence of impaired vascularity (may need</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Wound irrigation</div><div class=\"answer-line\">Reduction</div><div class=\"answer-line\">Immobilisation and Elevation</div><div class=\"answer-line\">IV Antibiotics – ie cephazolin 1gm tds</div><div class=\"answer-line\">ADT if not up to date</div><div class=\"answer-line\">Admission under orthopaedics for operative repair</div><div class=\"answer-line\">Ongoing close neurovascular obs distally for compartment concerns once immobilised</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 4 year old boy has been diagnosed with diabetic ketoacidosis as a first presentation of diabetes mellitus.","parts":[{"id":"a","label":"Part A","prompt":"List 4 distinct abnormalities you would expect to find on a venous blood gas. Explain the likely cause of each. (4 marks) Abnormality Cause\nHis vital signs are:\n\nGCS\nPulse 145 /min\n\nBP\n90/40 mmHg O2 sats 99% room air"},{"id":"b","label":"Part B","prompt":"State 4 therapies you might institute during the first 4 hours of his ED stay. Provide end-points where appropriate. (4 marks)"},{"id":"c","label":"Part C","prompt":"List 3 potential complications that might arise while the patient is in ED. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">HAGMA – ketones</div><div class=\"answer-line\">Hyperkalaemia – usually from H+ shift, potential for renal injury</div><div class=\"answer-line\">Hypocapnoea – respiratory compensation for metabolic acidosis</div><div class=\"answer-line\">High Base Deficit – direct reflection of metabolic acidosis</div><div class=\"answer-line\">Hyponatraemia – dilutional from hyperglycaemia</div><div class=\"answer-line\">Hyperglycaemia – from impaired transport into cells and elevated glycogenolysis from stress state</div><div class=\"answer-line\">Hyperlactataemia – from stress state (not accept hypoperfusion)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Insulin </strong>infusion – 0.01u/kg IV – end-point of termination of ketosis</div><div class=\"answer-line\">IV fluid therapy – maintenance + deficit over 24/48 hrs – end-point of mucous membranes/ cap refill</div><div class=\"answer-line\">(not urine output as will be impacted by osmotic diuresis)</div><div class=\"answer-line\"><strong>Potassium replacement</strong> – 40mmol in each litre of IV fluid – initiate once serum K &lt;5, end-point</div><div class=\"answer-line\">maintenance of normokalaemia (ie K &gt;4)</div><div class=\"answer-line\">Glucose therapy – as part of maintenance fluid (5% + N/S) once BSL &lt;15 – to avoid iatrogenic</div><div class=\"answer-line\">hypoglycaemia – end-point BSL &gt;5 (or similar)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cerebral oedema from fluid shift into cells upon correction of hyperglycaemia + rehydration</div><div class=\"answer-line\">Hypoglycaemia from rapid shift into cells on insulin infusion</div><div class=\"answer-line\">Hypokalaemia from insulin-driven intracellular shift</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 65 year old man has presented with large volume haemoptysis.","parts":[{"id":"a","label":"Part A","prompt":"List 5 investigations you would perform. Provide justification for each. (5 marks)\nThe patient has ongoing large volume bleeding. You have elected to intubate the patient to facilitate further management. The patient’s vital signs are:\n\nGCS\nE4 V4 M6 Pulse 135 /min\n\nBP\n85/40 mmHg O2 sats 91% 15L O2 via non-rebreather mask"},{"id":"b","label":"Part B","prompt":"State 5 components of your management in the peri-intubation period specific to this patient. Provide justification for each. (5 marks) Shortly after establishing ventilation, the ventilator has begun to alarm with high pressures."},{"id":"c","label":"Part C","prompt":"List 5 potential causes of this problem relevant to this patient. (5 marks)"},{"id":"d","label":"Part D","prompt":"List 3 options for definitive management of this patient’s large volume haemoptysis. For each, provide specific clinical circumstances that would make it the most appropriate option. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>FBE – assess Hb/ Platelets</td><td>COAGs – assess for intrinsic coagulopathy/synthetic dysfunction</td></tr><tr><td>CXR – assess for evidence of underlying cause ie lung malignancy, pulmonary vasculitis</td><td>Group + Hold – as a precaution for probable transfusion requirement</td></tr><tr><td>Chem20 for renal function – in cases where suspicion exists of underlying vasculitis</td><td>VBG – assess for respiratory status ie respiratory acidosis</td></tr><tr><td>ABG – assess for degree of shunt from non-ventilated lung</td><td>CT Angio Thorax – assess for amenability to interventional radiological therapy (ie embolisation)</td></tr><tr><td>CT Thorax with contrast – where malignancy is suspected to assess lesion + evidence of nodal</td><td>involvement that may impact therapeutic choice</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Pre-intubation:</td><td>Position – sit upright where tolerated to allow patient to self-clear blood</td></tr><tr><td>Fluid bolus (accept blood) to address hypotension – ie 10ml/kg IV saline aim MAP &gt;65mmHg</td><td>Improve pre-oxygenation with addition of either hHFNPs @ 60lpm or NPO2 @ 15lpm OR BiPAP</td></tr><tr><td>(many may not include this due to haemopytsis but would be acceptable if tolerated due to ability to</td><td>use PEEP – ie 10-15cm H20) to improve oxygenation</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Tube obstruction from clots/blood</div><div class=\"answer-line\">Tube malposition due to impaired view at intubation from blood ie RMB</div><div class=\"answer-line\">Collapse from blood overcoming surface tension</div><div class=\"answer-line\">Incorrect settings with pressure limit not adjusted for patient factors</div><div class=\"answer-line\">Anaphylaxis to induction agents</div><div class=\"answer-line\">Inadequately sedated/paralysed patient due to reduced agent use – desynchrony</div><div class=\"answer-line\">Tension PTX from PPV with higher vent pressures to address hypoxia – barotrauma</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Endobronchial/bronchoscopic - specific bleeding focus without blush on CTA</td><td>Surgical – extrabronchial mass/lesion with large volume bleeding; multiple bleeding sites;rescue for</td></tr><tr><td>other methods</td><td>Interventional Radiology – clear single bleeding focus with bronchial arterial blush on CTA</td></tr><tr><td>?accept medical ie pulse methylpred 1gm IV if vasculitic bleeding?</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 5 year old boy has been brought to the ED after being bitten by a snake on a farm in North Queensland.","parts":[{"id":"a","label":"Part A","prompt":"State 4 features of your examination, including justification. (4 marks)\nA coagulation profile was collected. The results are provided below."},{"id":"b","label":"Part B","prompt":"Interpret the results. (2 marks) The patient has normal vital signs."},{"id":"c","label":"Part C","prompt":"State the primary component of your management. (1 mark)"},{"id":"d","label":"Part D","prompt":"List 4 complications of the condition demonstrated by the blood results and/or its management. (4 marks)\nPAH 2023.1 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":["asset:img0d819aa9e83c157a92"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bite site and local area – bruising/bleeding/lymph nodes</div><div class=\"answer-line\">Skin/oral cavity etc – evidence of haemorrhage</div><div class=\"answer-line\">Neurologic exam – ptosis/EOM palsy/cerebellar exam suggesting neurotox</div><div class=\"answer-line\">Respiratory status for T2 respiratory failure from resp muscle weakness</div><div class=\"answer-line\">Vital signs for systemic signs envenoming</div><div class=\"answer-line\">Must be more....</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Profound coagulopathy with elevated D-Dimer consistent with VICC (Venom Induced Consumptive</div><div class=\"answer-line\">Coagulopathy) Confirmation of Envenoming and indication for antivenom administration</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Antivenom administration (polyvalent most appropriate given possible snake type) 1 ampoule IV</div><div class=\"answer-line\">1:10 dilution over 15-30mins</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Microvascular thrombi leading to organ dysfunction (ie renal failure)</div><div class=\"answer-line\">MAHA</div><div class=\"answer-line\">Peripheral “trashing” with embolic ischaemia ie digital infarcts</div><div class=\"answer-line\">Major haemorrhage with biggest risks of intracranial bleeding/GIT bleeding or other non-</div><div class=\"answer-line\">compressible bleeding focus</div><div class=\"answer-line\">Anaphylaxis to antivenom administration</div><div class=\"answer-line\">Serum sickness delayed reaction to antivenom</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 5 year old girl has been brought to the ED after falling off a swing on to her head.","parts":[{"id":"a","label":"Part A","prompt":"List 4 examination findings that would indicate a traumatic lesion causing raised intracranial pressure. (4 marks) A CT of her head is provided below."},{"id":"b","label":"Part B","prompt":"State the pathology demonstrated, with 3 radiographic abnormalities. (4 marks) Pathology Radiographic abnormalities Upon returning to the ED after the CT scan, the patient has a seizure.\nHer vital signs are:\nPulse /min\n\nBP\n160/55 mmHg O2 sats 98% room air"},{"id":"c","label":"Part C","prompt":"State 4 components of your management. (4 marks)"}],"propPages":["asset:img104feff56b2cb4e071"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Reduced GCS</div><div class=\"answer-line\">Agitation/irritability</div><div class=\"answer-line\">Unequal/poorly responsive pupils</div><div class=\"answer-line\">Relative bradycardia and hypertension (do not accept Cushings reflex without details of</div><div class=\"answer-line\">haemodynamics)</div><div class=\"answer-line\">Decorticate or Decererbrate posturing (unilateral or bilateral)</div><div class=\"answer-line\">Seizures</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Left convexed hyperdensity</div><div class=\"answer-line\">Constrained by suture lines</div><div class=\"answer-line\">Rightward midline shift</div><div class=\"answer-line\">Mixed density suggesting active arterial bleeding</div><div class=\"answer-line\">Ventricular effacement</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Midazolam for seizure termination</div><div class=\"answer-line\">Intubation</div><div class=\"answer-line\">Hyperventilation given seizure and cushings reflex – aim PaCO2 (accept ETCO2) 30mmHg</div><div class=\"answer-line\">ICP lowering therapy – 3% saline 3mLs/kg or Mannitol 0.5gm/kg as bolus aim seizure termination or</div><div class=\"answer-line\">normalisation of haemodynamics</div><div class=\"answer-line\">Urgent neurosurgical attendance for OT</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 75 year old female has presented with a 12 hour history of severe abdominal pain and vomiting. A venous blood gas is provided below. Reference range\n\npH\n7.31 7.35 - 7.45\n\npCO2\nmmHg 40 - 50\n\nHCO3\nmmol/L 24 - 32\n\nNa+\n140 mmol/L 135 - 145\n\nK+\n4.2 mmol/L 3.5 - 5.1\n\nCl -\nmmol/L 95 - 110","parts":[{"id":"a","label":"Part A","prompt":"List 3 pathological processes present. For each, provide the relevant calculations and a likely cause. (9 marks) Pathological process Calculations Likely cause You are concerned about the possible diagnosis of ischaemic bowel."},{"id":"b","label":"Part B","prompt":"List 4 risk factors for mesenteric arterial occlusion. (4 marks)"},{"id":"c","label":"Part C","prompt":"Apart from a venous blood gas, list and justify 5 investigations you would perform. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>HAGMA – 140 - (95+16) = 29 – lactic acidosis</td><td>Resp acidosis –expected CO2 of: (1.5 x 16)+8 = 32 – hypoventilation from abdominal splinting/pain</td></tr><tr><td>Met alk –  delta ratio of 29-12(17)/24-16(8) = 2 – acid loss from vomiting</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Atrial fibrillation</div><div class=\"answer-line\">Atherosclerosis – ie smoking/hyperchol/hypertension</div><div class=\"answer-line\">Congestive heart failure</div><div class=\"answer-line\">Left sided Valvular disease</div><div class=\"answer-line\">Vasculitides</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">CT angio abdomen – confirm diagnosis, extent of ischaemia, exclude differentials</div><div class=\"answer-line\">ECG – assess for atrial fibrillation as potential cause</div><div class=\"answer-line\">Renal function – assess for concurrent acute renal failure, proximal occlusion, impact on therapies</div><div class=\"answer-line\">Lactate – progression of lactic acidosis/gut hypoperfusion</div><div class=\"answer-line\">Coags – exclude coagulopathy as may require operative management</div><div class=\"answer-line\">Group &amp; Hold – if considering operative management</div><div class=\"answer-line\">CXR – assess for aspiration/anaesthetic safety (ie cardiac status)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 58 year old female has presented with lethargy.\nHer Full Blood Count is shown below: Units Reference Range Haemoglobin g/L 115 - 160 White Cell Count 9.6 x10^9/L 3.5 - 11.0\n\nPlatelet Count\n160 x10^9/L 140 - 400 Haematocrit 0.21 0.35 - 0.51 MCH 29.4 pg 27.5 - 34.5 Red Cell Count 2.2 x10^12/L 3.50 - 6.00 MCV 115 fl 80 - 100","parts":[{"id":"a","label":"Part A","prompt":"Interpret the results shown. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 6 features of your history or examination aimed at identifying the cause of the\nabnormalities shown. Provide justification for each. (6 marks)"},{"id":"c","label":"Part C","prompt":"List 3 further investigations you would perform to identify the cause of the abnormalities shown. Provide justification for each. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Macrocytic anaemia</div><div class=\"answer-line\">Low Hb, high MCV</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>B12/folate def – hx – poor diet, vegetarian/vegan; ex – peripheral neuropathy, glossitis, stomatitis</td><td>Alcohol abuse – hx of alcohol abuse; ex – currently intoxicated/signs of cerebellar disease</td></tr><tr><td>Liver disease – hx – known chronic liver disease; ex – ascites, icterus, spider naevi</td><td>Hypothyroidism – hx of lethargy/cold/ iatrogenic (ie on Carbimazole), recent viral illness with neck</td></tr><tr><td>pain or examination features, bradycardia, hypothermia, skin changes or hung up reflexes</td><td>Drug induced – hx of chemotherapy agents</td></tr><tr><td>Haemolysis – hx of myelodysplastic syndrome/valvular disease or IVDU, exam – petechiae, murmur</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>TFTs</td><td>LFTs</td></tr><tr><td>Serum B12/folate levels</td><td>Blood film for schistocytes, nucleated RBCs</td></tr><tr><td>Reticulocyte count or haptoglobin– assess for haemolysis</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 55 year old man has presented to the ED complaining of sudden onset vertigo.","parts":[{"id":"a","label":"Part A","prompt":"List 4 causes of peripheral vertigo. For each, state discriminatory findings on history.\n(8 marks) Cause Discriminatory historical findings"},{"id":"b","label":"Part B","prompt":"Complete the following table regarding examination findings of the HINTS exam. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>BPPV – short, self-limiting episodes on movement</td><td>Vestibular neuritis – recent URTI, continuous</td></tr><tr><td>Labyrinthitis – hearing loss with recent URTI, continuous</td><td>Meniere’s disease – chronic episodic vertigo, tinnitus/hearing loss</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Head impulse – peripheral = corrective saccade; central = normal</div><div class=\"answer-line\">Nystagmus – peripheral = horizontal/unidirectional; central = torsional/ bi-directional</div><div class=\"answer-line\">Test of skew – peripheral = no skew; central = skew deviation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 16 year old girl has presented after a syncopal episode at school.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your cardiovascular examination. Include the clinical relevance. (4 marks) An ECG is provided below."},{"id":"b","label":"Part B","prompt":"State the abnormality shown and provide the clinical implication. (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 distinct causes of this abnormality. (3 marks)\nShortly after arriving, the patient becomes unconscious. There is no palpable pulse. The following rhythm is witnessed on her cardiac monitor."},{"id":"d","label":"Part D","prompt":"State 3 key features of your initial management. (3 marks)\nYour initial management has resulted in a return of spontaneous circulation and consciousness. The patient continues to have intermittent episodes of dizziness with self-limiting runs of the rhythm demonstrated above."},{"id":"e","label":"Part E","prompt":"State 2 options for the management of this problem. Include details of each treatment option. (2 marks) Your management has been successful and the patient is awaiting admission to an appropriate hospital bed. The nursing staff have informed you that the patient is wishing to self-discharge so that she can go to a party with her boyfriend."},{"id":"f","label":"Part F","prompt":"State 4 key features of your management of this situation. (4 marks)"}],"propPages":["asset:img82788c4b423ee24ad8","asset:img2ffcbf274793520fa9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">ESM – aortic stenosis</div><div class=\"answer-line\">S4 heart sound, double apical impulse – HOCM</div><div class=\"answer-line\">Postural BPs – orthostatic hypotension</div><div class=\"answer-line\">Pulse rate/regularity – underlying tachycardic/bradycardic arrhythmia</div><div class=\"answer-line\">Signs of anaemia – conjunctival pallor</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Long QT</div><div class=\"answer-line\">Torsades leading to syncope</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypokalaemia</div><div class=\"answer-line\">Hypomagnesaemia</div><div class=\"answer-line\">Drug induced – antipsychotics/TCAs/antidepressants, macrolide antibiotics</div><div class=\"answer-line\">Congenital long QT syndromes</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Magnesium IV 10mmol load</div><div class=\"answer-line\"><strong>CPR 30:2  </strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Chemical pacing – isoprenaline or adrenaline aiming HR &gt;100</div><div class=\"answer-line\">Electrical pacing – transcutaneous in ED with rate &gt;100</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Assess competence / ability to make informed consent</div><div class=\"answer-line\">Explain diagnosis and threat to life</div><div class=\"answer-line\">Explore reasoning for wanting to discharge</div><div class=\"answer-line\">Involve social work or social supports</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 48 year old male with type 1 diabetes has presented with progressive otitis externa despite 2 weeks of topical antimicrobial therapy.","parts":[{"id":"a","label":"Part A","prompt":"List 4 complications you would seek. Provide the examination findings that would support the presence of each. (8 marks) Complication Supportive examination findings"},{"id":"b","label":"Part B","prompt":"List 2 likely organisms that could be causing this problem. (2 marks)"},{"id":"c","label":"Part C","prompt":"List 2 different antibiotic options for intravenous therapy in this man. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Necrotising otitis externa – erythematous thickened cartilage</div><div class=\"answer-line\">Mastoiditis – erythema and tenderness over mastoid process</div><div class=\"answer-line\">Meningitis - signs of meningism,</div><div class=\"answer-line\">cerebral abscess- focal neurologic signs or seizures</div><div class=\"answer-line\">Facial nerve involvement – unilateral LMN signs</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pseudomonas</div><div class=\"answer-line\">Staph aureus</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV piptaz 4.5g Q6H</div><div class=\"answer-line\">IV ceftazidime 2g Q8H</div><div class=\"answer-line\">IV Ciprofloxacin 450mg tds</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 9 month old boy has been referred to the ED by his LMO who was concerned about the possible diagnosis of intussusception.","parts":[{"id":"a","label":"Part A","prompt":"List 4 findings on history that would support the diagnosis of intussusception. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 investigations you might perform. Provide justification for each. (3 marks)\nFollowing your assessment, intussusception has been confirmed. The patient has the following vital signs: AVPU alert Pulse 140 /min\n\nBP\n90/40 mmHg\n\nRR\n/min O2 sats 99% room air"},{"id":"c","label":"Part C","prompt":"State 3 components of your management. (3 marks)"},{"id":"d","label":"Part D","prompt":"List 2 complications of intussusception. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Intermittent episodes of pain or distress</div><div class=\"answer-line\">Red-currant jelly stool</div><div class=\"answer-line\">Appears well between episodes</div><div class=\"answer-line\">Pallor during episodes</div><div class=\"answer-line\">Lethargy</div><div class=\"answer-line\">Vomiting</div><div class=\"answer-line\">Risk factors – recent intussusception, lead point (lymphoma/meckels), recent bowel surgery, recent</div><div class=\"answer-line\">rotavirus vaccination</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><strong>Ultrasound abdomen</strong> – confirm diagnosis</td><td>AXR – assess for associated bowel obstruction/perforation</td></tr><tr><td>VBG – assess for hypoperfusion</td><td>BSL – exclude hypoglycaemia</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – IN fentanyl 1.5mcg/kg, IV morphine 0.1mg/kg</div><div class=\"answer-line\">IV maintenance fluids (note this child NOT shocked therefore bolus fluid inappropriate)</div><div class=\"answer-line\">IV antibiotics – amoxicillin, gentamicin, metronidazole (now part of RCH guideline)</div><div class=\"answer-line\"><strong>Urgent surgical/radiology referral</strong> for contrast/gas enema reduction</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bowel obstruction</div><div class=\"answer-line\">Bowel ischaemia</div><div class=\"answer-line\">Perforation</div><div class=\"answer-line\">Hypovolaemic shock</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 24 year old woman has presented after a fall whilst playing professional netball.\nShe has a painful left wrist. It is an isolated injury.","parts":[{"id":"b","label":"Part B","prompt":"Describe the abnormalities shown. (3 marks)"},{"id":"c","label":"Part C","prompt":"State 4 features of your examination, including the clinical relevance. (4 marks)"},{"id":"d","label":"Part D","prompt":"State 5 components of your management of this patient. (5 marks)"}],"propPages":["asset:img2e2aaf81adfd2b0370"],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["rays are provided below."],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Dorsally displaced distal carpal row</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ulnar nerve</div><div class=\"answer-line\">Radial nerve</div><div class=\"answer-line\">Ulna artery</div><div class=\"answer-line\">Hand perfusion/cap refill</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Analgesia – something reasonable</div><div class=\"answer-line\">Reduction under sedation</div><div class=\"answer-line\">Cast thumb spica</div><div class=\"answer-line\">Elevation for swelling</div><div class=\"answer-line\">Ortho referral for admission and definitive fixation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 68 year old man has been brought to the ED with chest pain and lethargy after waking today.\nHe has a history of stage 4 chronic kidney disease, hypertension and hyperlipidaemia.\nHis vital signs are:\n\nHR\n110 /min\n\nBP\n75/46 mmHg\n\nTemp\n37.6 degrees\n\nRR\n/min Sa02 88% room air","parts":[{"id":"a","label":"Part A","prompt":"List 6 potential causes for this presentation. For each, provide a discriminatory assessment finding (history, examination or investigation). (12 marks) Cause Assessment feature"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Cause</td><td>Assessment Feature</td></tr><tr><td>Congestive Cardiac Failure</td><td>Bilateral Crackles</td></tr><tr><td>Pericardial Tamponade</td><td>Effusion on bedside US with features of tamponade</td></tr><tr><td>Pneumonia</td><td>Focal crackles/fever</td></tr><tr><td>Pulmonary Embolus</td><td>Peripheral signs DVT, Bedside US with thin, dilated RV</td></tr><tr><td>/clot/McConnels etc</td><td></td></tr><tr><td>Progressive Aortic Stenosis</td><td>ESM</td></tr><tr><td><strong>Acute MI</strong> with LV failure</td><td>Elevated Troponin, ischaemic ECG</td></tr><tr><td>Acute MI with acute MR</td><td>pan-systolic murmur at axilla, haemoptysis</td></tr><tr><td>Iatrogenic (excess BP Meds)</td><td>Medication review</td></tr><tr><td>Aortic dissection with true (ie pericardial effusion) or pseudohypotension (brachial a. involvement)</td><td></td></tr><tr><td>pulse deficit, murmur of Aortic Regurgitation (diastolic rumble)</td><td></td></tr><tr><td>(HyperK/ AV blocks unlikely and not accepted given HR 110/min)</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
